using System;
using Outbreak.Contracts;
using Outbreak.Core;
using Outbreak.Persistence;
public static partial class Program
{
    private static void CheckHouseholdCases()
    {
        Check("Household rosters separate assigned residents away couriers and physical visitors",()=>{
            World world=EncounterScenarios.HouseholdManagementTest();string before=State(world);HouseholdOverview[] rows=world.Households();Require(rows.Length==3 && rows[0].HouseId==183 && rows[1].HouseId==192 && rows[2].HouseId==222,"Household geometry order changed.");Require(rows[0].Residents.Length==2 && rows[0].AtHome==1 && rows[0].Away==1 && rows[0].Visitors==0 && rows[0].Boxes==1,"Home roster counts confused assignment and occupancy.");Require(rows[1].Residents.Length==1 && rows[1].AtHome==1 && rows[1].Visitors==1 && rows[2].Residents.Length==0,"Visitor became a resident or empty house disappeared.");Require(rows[0].Residents[0].Id==1 && rows[0].Residents[0].Courier && !rows[0].Residents[0].AtHome && rows[0].Residents[0].CurrentHouseId==192,"Away courier lost permanent home membership.");rows[0].Residents[0].Id=-1;rows[0].Residents=new HouseholdResident[0];Require(State(world)==before && world.Households()[0].Residents[0].Id==1,"Household read model mutated the world.");
        });
        Check("Moving a resident preserves courier routes cargo position and exact saved continuation",()=>{
            World world=EncounterScenarios.HouseholdManagementTest();ActorState before=world.ActorAt(0);int meals=world.FoodSupplies().RemainingMeals;Require(world.TryAssignHouse(0,42,3),"Could not reassign away courier.");ActorState after=world.ActorAt(0);Require(after.assignedHouseId==222 && after.x==before.x && after.y==before.y && after.courierSourceBox==before.courierSourceBox && Documents.Encode(after.courierBoxes)==Documents.Encode(before.courierBoxes) && world.FoodSupplies().RemainingMeals==meals,"Home move teleported resident, changed cargo or rewrote delivery route.");Require(world.Households()[0].Residents.Length==1 && world.Households()[2].Residents.Length==1 && world.Households()[2].Away==1,"Reassignment left duplicate roster membership.");World copy=Documents.ParseSave(State(world));for(int i=0;i<30;i++){world.Step();copy.Step();Require(State(world)==State(copy),"Household reassignment diverged after save.");}string busy=State(world);Require(!world.TryAssignHouse(0,3,6) && !world.TryUnassignHouse(0) && State(world)==busy,"Busy courier home edit changed task state.");
        });
        Check("Removing a home is explicit and protects courier routes and return goals",()=>{
            World world=EncounterScenarios.HouseholdManagementTest();string before=State(world);Require(!world.TryUnassignHouse(0) && !world.TryUnassignHouse(-1) && !world.TryUnassignHouse(3) && State(world)==before,"Invalid home removal changed state.");Require(world.TryUnassignHouse(1) && world.ActorAt(1).assignedHouseId==0 && world.Households()[0].Visitors==1,"Resident unassignment failed or removed physical visitor.");Require(world.TryClearCourierRoute(0) && world.TryUnassignHouse(0) && world.ActorAt(0).courierSourceBox==0,"Cleared courier route still prevented home removal.");world=EncounterScenarios.HouseholdManagementTest();world.TryClearCourierRoute(0);SaveDocument saved=world.Capture();saved.actors[0].courierReturningHome=true;saved.actors[0].homeShelterId=183;saved.actors[0].shelterId=183;saved.actors[0].shelterX=3;saved.actors[0].shelterY=5;saved.actors[0].shelterState=ShelterState.Seeking;world=World.Restore(saved);Require(world.TryUnassignHouse(0) && world.ActorAt(0).homeShelterId==0 && world.ActorAt(0).shelterId==0 && !world.ActorAt(0).courierReturningHome,"Unassignment retained forced travel to old home.");Require(State(Documents.ParseSave(State(world)))==State(world),"Unassigned return state could not reload.");
        });
        Check("Household roster excludes dead and converted humans and identifies infected members",()=>{
            SaveDocument saved=EncounterScenarios.HouseholdManagementTest().Capture();saved.actors[1].turnAtTick=1;World world=World.Restore(saved);Require(world.Households()[0].Residents[1].Infected,"Infected resident was silently removed from roster.");string before=State(world);Require(!world.TryAssignHouse(1,42,3) && !world.TryUnassignHouse(1) && State(world)==before,"Infected resident could be reassigned.");world.Step();Require(world.Households()[0].Residents.Length==1 && world.ActorAt(1).species==Species.Zombie,"Converted human remained a resident.");saved=EncounterScenarios.HouseholdManagementTest().Capture();saved.actors[3].health=0;world=World.Restore(saved);Require(world.Households()[0].Residents.Length==2 && world.Households()[1].Visitors==1,"Dead unassigned human changed living roster counts.");saved=EncounterScenarios.EnergyRestTest().Capture();saved.rulesVersion=EncounterRules.DeliveryControlsVersion;world=World.Restore(saved);Require(world.Households().Length==0 && !world.TryUnassignHouse(0),"Legacy rules exposed unavailable household assignments.");
        });
    }
}
